#!/usr/bin/env bash
# B3d = B3a with ONE factor changed: + --aug_codec_profiles random (per-clip random Opus bitrate {6,8,12,16,24} kbps / frame {20,40,60} ms / VBR mode / packet-loss hint; everything else identical to B3a, incl. --consistency js --consistency_lambda 0.3 --consistency_pairs both --batch_size 8)
#   generated by exploop (wave B3, iteration 4) from exploop/B3/iter04/design.result.json
#  B3d = B3a with one flag added: --aug_codec_profiles random. Every training clip still goes
#    through one of the same 7 Opus app profiles (same app draw, cutoff and application). Bitrate
#    is now drawn from {6,8,12,16,24} kbps, frame size from {20,40,60} ms, VBR from
#    off/on/constrained, plus a packet-loss hint (0, or 5-20 %). Everything else is identical to
#    B3a: - --consistency js --consistency_lambda 0.3 --consistency_pairs both, --batch_size 8 = 8
#    pairs = 16 clips/step; - 8 epochs, LR 2.5e-6 warmup-cosine to 5e-7; - sampler shuffle, CE
#    weights 0.1 0.9; - RTC aug + MUSAN, SNR 5-20 dB, loudness norm -23. It runs ~8 h. Evidence: -
#    B3a (JS 0.3) is the reference: merge half_B 93.06. - B3b (sampler) was negative at -0.83
#    [-1.46, -0.25]: not exposure, not the operating point. - B3c (lambda 1.0) was negative at
#    -0.77 [-1.31, -0.22]: more invariance on the same augmentation distribution hurt heldout. - On
#    B3a-top5, 112 of the 180 half_B noisy bona false alarms sit in heldout g726 / gsm and matched
#    opus:qq / wechat. - The fixed profiles draw 0.473 of codec passes above 24 kbps and only 0.084
#    at or below 12 kbps. Random draws 0.600 at or below 12 kbps. Target: low-bitrate and
#    unseen-codec bona false alarms. g726 / gsm stay reserved, so any heldout gain must come from
#    generalisation. Rule against B3a-top5 = 93.06 on half_B: promote if the delta is > +0.5, the
#    CI excludes 0 and the clean drop is <= 0.5; null within +-0.5; negative below -0.5.
#  Why: Largest remaining error (B3c report §5.4, largest_remaining_error): confident noisy bona
#    false alarms on the reference B3a-top5. They are 180 of 782 half_B noisy bona, 77 % of them at
#    p_spoof >= 0.99. The largest localised block is by codec: heldout g726 36/129, heldout gsm
#    38/127, matched opus:qq 21/60 and opus:wechat 17/50, which together hold 112 of the 180. SNR 0
#    holds 40, the next block. What the wave has ruled out so far: - B3b (sampler, -0.83 [-1.46,
#    -0.25]): exposure and the operating point. - B3c (lambda 1.0, -0.77 [-1.31, -0.22],
#    verdict.json): more invariance on the existing augmentation distribution. Heldout carried most
#    of the loss, and the saturated tail sharpened. The analyst concludes that the open levers are
#    the coverage of the training degradation distribution and regularisation. `codec_random` is
#    the next queued lever in wave.json, and the analyst ranked it first. Why codec coverage is a
#    real gap (derivation, computed from the two profile tables): - The fixed profiles concentrate
#    on high bitrates: 0.473 of draws are above 24 kbps, only 0.084 are at or below 12 kbps, and
#    the mean is 24.43 kbps. - The random profile puts 0.600 of draws at or below 12 kbps (mean
#    13.20). It raises the share of 40/60 ms frames from 0.143 to 0.667 and adds VBR modes and
#    packet-loss hints. - The two weakest matched codecs on B3a (full sets) are the low-bitrate
#    apps: opus:qq (R_bona 68.69) and opus:wechat (72.12). The reserved heldout codecs g726 and gsm
#    sit at 71.14 and 72.76. Low-rate, narrowband channel artefacts are exactly what the fixed
#    table under-samples. Constraints: - One flag, in `allowed`, outside every coupled group. The
#    consistency group (js, 0.3, both, --batch_size 8) is untouched, nothing forbidden or fixed is
#    touched, and the run stays at 8 of max 10 epochs. - Reserved ops are safe: the random profile
#    still encodes only with libopus (assert_training_ops checks this at start-up). `-packet_loss`
#    is a libopus encoder hint, not the reserved packet_loss filter. g726/gsm stay unseen, so any
#    heldout gain must come from generalisation. - The path was smoke-tested (b3wave README, "train
#    j"). Codec failures print "failed (", which the early check forbids. Why not the alternatives:
#    - snr_0_20 targets a smaller block (40 of 180) and is the natural iteration 5 if this one is
#    null. - SpecAugment targets over-fitting, a secondary symptom. - lambda 0 is a recipe control
#    with a smaller expected gain. - A seed repeat is not warranted while configuration levers that
#    the evidence supports remain.
#  Hypothesis: Heldout-codec and low-bitrate bona false alarms are a coverage problem. The model
#    has learned "heavy low-rate codec artefact implies spoof" because the bona it saw in training
#    passed almost only through mid/high-bitrate Opus: 0.473 of draws above 24 kbps and 0.084 at or
#    below 12 kbps. Randomising bitrate, frame size, VBR and the packet-loss hint per clip exposes
#    bona and spoof alike to strong low-rate artefacts. Then: - CE can no longer use the artefact
#    level as a spoof cue. - The paired JS at 0.3, with each view drawing its own random codec,
#    makes the decision invariant across codec parameters. That is invariance on a wider
#    distribution, not more weight on the same one, which B3c showed to be harmful. Expected
#    effect: the confident bona false alarms on qq/wechat drop because those conditions are now
#    covered directly. g726/gsm improve through generalisation from the low-rate Opus artefacts,
#    which share the band limitation and coarse quantisation. Spoof recall holds, because the
#    synthetic-speech cue does not live in the codec artefacts.
#  Expected signature: Merge vs B3a-top5 (half_B WF1 93.06); ep8 vs B3a-ep8 (92.94): - Codec slices
#    (full sets, metrics.json breakdowns): - heldout g726 / gsm R_bona >= 3 points above 71.14 /
#    72.76, with EER below 10.74 / 13.91; - matched opus:qq / opus:wechat R_bona >= 3 points above
#    68.69 / 72.12, with EER below 9.20 / 12.28; - g722 roughly flat (81.01 R_bona, 6.96 EER). -
#    half_B false alarms (merge): g726 + gsm below 74, qq + wechat below 38, total noisy bona false
#    alarms below 180 of 782. Noisy bona share at p >= 0.99 not above 17.6 %. - Sets: - heldout
#    half_B F1 above 90.20 and R_bona above 74.94, carrying most of the gain; - matched R_bona
#    above 79.03; - mean noisy EER below 9.16 (ranking, not threshold). - Unchanged: - R_spoof
#    within 0.5 of 99.38 (matched) / 99.06 (heldout); - clean F1 within 0.5 of 97.48; -
#    high-bitrate matched opus:zoom / opus:lark R_bona within 3 of 82.08 / 84.03, although the
#    random profile drops all > 24 kbps draws. - Telemetry: the per-epoch "B3 aug codec:" counts
#    stay balanced across the 7 apps, and there are no "(random profile) failed" lines. - Headline:
#    merge half_B WF1 above 93.06.
#  Derivation: python3 -I: share of codec draws under the fixed CODEC_PROFILES
#    (SLS_setup/utils/rtc_augment.py lines 166-174: integer kbps drawn uniformly in each app's
#    range, apps equiprobable) vs the random profile (SLS_setup/b3wave/augment.py RTCAugConfigB3:
#    kbps {6,8,12,16,24}, frames {20,40,60}, VBR off/on/constrained, packet-loss hint 0 w.p. 0.5
#    else U{5..20}): share of codec draws le 8 kbps: fixed 0.011 random 0.400 share of codec draws
#    le 12 kbps: fixed 0.084 random 0.600 share of codec draws le 16 kbps: fixed 0.191 random 0.800
#    share of codec draws above 24 kbps: fixed 0.473 random 0.000 share with frame ge 40 ms: fixed
#    0.143 random 0.667 mean kbps: fixed 24.43 random 13.20 Reference slice values (B3a merge_top5
#    metrics.json, full sets, breakdowns.codec): matched opus:qq R_bona 0.6869 EER 0.0920;
#    opus:wechat 0.7212 / 0.1228; opus:zoom 0.8208 / 0.0790; opus:lark 0.8403 / 0.0850; heldout
#    g722 0.8101 / 0.0696; g726 0.7114 / 0.1074; gsm 0.7276 / 0.1391. half_B (same file): wf1
#    0.93056, f1_clean 0.97484, eer_noisy 0.09159; matched R_bona 0.7903 R_spoof 0.9938; heldout f1
#    0.902 R_bona 0.7494 R_spoof 0.9906. Header check (B3c nohup log
#    SLS_setup/B3c_..._20261010234154.log): "SNR: 5..20 dB dist=uniform | Chaining: max_stages=1 |
#    Codec profiles: fixed". train.py line 626-628 prints the same line with "Codec profiles:
#    random". Without --use_level_aug, build_augmenter_b3 returns the RTCAugmenterB3 itself as the
#    dataset augmenter, so the "RTC augmentation:" line gets " | codec_profiles=random kbps=[6, 8,
#    12, 16, 24] frames=[20, 40, 60] vbr=rand loss=0|5-20" appended (augment.py describe()).
#  Eval note: Evaluate both readouts with --loudness_norm --loudness_norm_lufs -23 (read from
#    config.yaml): the top-5 merge (the objective) and epoch_8. Checkpoints are plain ModelSLS
#    state_dicts. Compare against B3a-top5 / B3a-ep8 (the current best) and the fixed comparators
#    B2f-top5 / B2f-ep8, with the paired-bootstrap CI at n 2000. Report: - full-set per-codec
#    R_bona / R_spoof / EER for all 7 matched opus apps and heldout g722 / g726 / gsm, against
#    B3a-top5; - half_B noisy bona false alarms split by codec, by SNR (SNR 0 separately) and by en
#    / zh; - the noisy bona share at p >= 0.99 / 0.999; - mean noisy EER and per-set R_bona; - the
#    best global logit threshold; - per-epoch CE / JS and dev loss vs B3a (same CE weights, so
#    directly comparable); - the per-epoch codec app counts from train.log, and confirm no "(random
#    profile) failed" lines in the nohup log. State which of falsifiers 1-4 fired.
#  Falsification (pre-registered): delta top-5-merge half_B.wf1.wf1 vs B3a merge (93.06) > +0.5
#    with the paired-bootstrap CI excluding 0 and clean F1 drop <= 0.5 -> positive; within +-0.5 ->
#    null; below -0.5 -> negative. Wave rule against B3a-top5 = 93.06 on half_B: - Promote /
#    positive: delta merge > +0.5, the paired-bootstrap CI excluding 0, and a clean F1 drop <= 0.5.
#    - Null: delta within +-0.5. - Negative: delta below -0.5. Mechanism-level refutations: 1.
#    Codec coverage is not the limit: delta within +-0.5 AND full-set g726 / gsm R_bona within +-3
#    of 71.14 / 72.76 AND qq / wechat R_bona within +-3 of 68.69 / 72.12. Move to the SNR range
#    (snr_0_20) or SpecAugment. 2. Covers seen codecs but does not generalise: qq / wechat R_bona
#    up >= 3 while g726 / gsm move less than 3. The heldout codec errors are not explained by Opus
#    parameter coverage. 3. Blurs a spoof cue: R_spoof down > 0.5 on matched or heldout. Random
#    low-rate profiles mask the synthesis artefacts. 4. Lost the high-bitrate mass: matched
#    opus:zoom / opus:lark R_bona down > 3, or a clean F1 drop > 0.5. Removing every > 24 kbps draw
#    hurt high-quality channels. A fixed/random mix would need code, so it is out of this wave.
#
#   bash scripts/run_B3d.sh                                   # fresh run (the exploop supervisor launches it)
#   bash scripts/run_B3d.sh --resume exp/<run dir name>       # after a container restart
#   EXPLOOP_PRINT_ARGV=1 bash scripts/run_B3d.sh              # print the trainer argv, launch nothing
#
# Rendered from scripts/exploop/launcher_template.sh (same shape as scripts/run_B3a.sh). Extra
# arguments are appended to the trainer command line. Training runs under nohup; stdout/stderr go to
# <workdir>/<track>_<timestamp>.log and the per-epoch summary to <run dir>/logs/train.log.
set -euo pipefail

PY="${PY:-/root/.conda/envs/rtc-sdd/bin/python}"
TRACK="B3d_qwen17_rtc_musan_loud23_cos8_lr2.5e6_cjs03_codecrand_s1234"
WORKDIR="/root/repos/rtc-sdd/Ghostbusters_team/SLS_setup"

ARGS=(
    --train_data_path /mnt/paml-research/RTCFake/data/wav/train
    --train_protocol /mnt/paml-research/RTCFake/data/train_label.txt
    --dev_data_path /mnt/paml-research/RTCFake/data/wav/dev
    --dev_protocol ../data/dev_noisy_sim/dev_label_excl_halfB.txt
    --ssl_name Qwen/Qwen3-ASR-1.7B
    --n_layers 24
    --batch_size 8
    --num_epochs 8
    --num_workers 64
    --use_rtc_aug
    --aug_noise_dirs ../data/augmentation_train/rnnoise ../data/augmentation_train/esc50
    --aug_rir_dirs ../data/augmentation_train/rirs
    --musan
    --musan_dir ../data/augmentation/musan
    --loudness_norm
    --loudness_norm_lufs -23
    --optim adamw
    --lr 2.5e-6
    --head_lr_mult 10
    --weight_decay 0.01
    --lr_scheduler warmup_cosine
    --warmup_frac 0.05
    --lr_min 5e-7
    --grad_clip 1.0
    --ema_decay 0.9995
    --local_eval_sets ../configs/local_eval_sets.yaml
    --earlystop_metric wf1
    --earlystop_epoch 99
    --keep_topk_by_wf1 7
    --keep_epochs 8
    --seed 1234
    --track "$TRACK"
    --consistency js
    --consistency_lambda 0.3
    --consistency_pairs both
    --aug_codec_profiles random
)

if [ "${EXPLOOP_PRINT_ARGV:-0}" = "1" ]; then
    printf '%s\n' "${ARGS[@]}"
    exit 0
fi

if [ ! -x "$PY" ]; then
    echo "python not found: $PY (set PY=... to override)" >&2
    exit 1
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
    echo "ffmpeg not found on PATH: the RTC codec augmentation would silently no-op. Reinstall it first." >&2
    exit 1
fi
if ! "$PY" -c "import pyloudnorm" >/dev/null 2>&1; then
    echo "pyloudnorm not importable by $PY: run '$PY -m pip install pyloudnorm==0.2.0' first." >&2
    exit 1
fi

cd "$WORKDIR"
LOG="${TRACK}_$(date +%Y%m%d%H%M%S).log"

nohup "$PY" -u -m b3wave.train "${ARGS[@]}" "$@" > "$LOG" 2>&1 &

PID=$!
echo "Started $TRACK (pid $PID)"
echo "Log:     $WORKDIR/$LOG"
echo "Follow:  tail -f $WORKDIR/$LOG"
echo "Stop:    kill $PID"
